// Interface languages. Like the web client, UI text is written as the Chinese source string:
// t('照片'), t('{n} 张照片', {'n': 3}). The Chinese text is the key; the other languages live in
// assets/i18n/<locale>.json, generated by tool/i18n.mjs from the web translations
// (web/src/i18n/locales) plus the app-only strings in i18n/<locale>.json.
// Plural entries are {"one": "...", "other": "..."}. A missing translation falls back to
// English, then to the Chinese source.

import 'dart:convert';
import 'dart:ui';

import 'package:flutter/services.dart';
import 'package:logging/logging.dart';

final _log = Logger('i18n');

const locales = ['en', 'zh-CN', 'zh-TW', 'ja', 'ko', 'de', 'fr', 'es', 'pt-BR', 'ru', 'it', 'vi'];

String _current = 'zh-CN';
Map<String, dynamic> _dict = {};
Map<String, dynamic> _fallback = {};

String get currentLocale => _current;

/// Maps a device or account language ("zh-Hant-HK", "pt", "en-GB") to a supported one.
String? matchLocale(String tag) {
  final t = tag.toLowerCase().replaceAll('_', '-');
  if (t.startsWith('zh')) return RegExp('hant|tw|hk|mo').hasMatch(t) ? 'zh-TW' : 'zh-CN';
  if (t.startsWith('pt')) return 'pt-BR';
  final base = t.split('-').first;
  for (final l in locales) {
    if (l.toLowerCase() == base) return l;
  }
  return null;
}

String deviceLocale() {
  for (final l in PlatformDispatcher.instance.locales) {
    final m = matchLocale(l.toLanguageTag());
    if (m != null) return m;
  }
  return 'en';
}

Future<Map<String, dynamic>> _load(String locale) async {
  if (locale == 'zh-CN') return {};
  try {
    return jsonDecode(await rootBundle.loadString('assets/i18n/$locale.json')) as Map<String, dynamic>;
  } on Object catch (e) {
    _log.warning('no translations for $locale', e);
    return {};
  }
}

/// Loads [locale] (an account setting or empty for the device language).
Future<void> setLocale(String locale) async {
  final l = (locale.isEmpty ? null : matchLocale(locale)) ?? deviceLocale();
  _dict = await _load(l);
  _fallback = l == 'en' || l.startsWith('zh') ? {} : await _load('en');
  _current = l;
}

/// Translates [key]; `{name}` placeholders are filled from [args]. When a plural entry is
/// used, the first numeric argument picks "one" or "other".
String t(String key, [Map<String, Object> args = const {}]) {
  var entry = _dict[key] ?? _fallback[key];
  if (entry is Map) {
    final n = args.values.whereType<num>().firstOrNull;
    entry = (n == 1 ? entry['one'] : null) ?? entry['other'] ?? entry.values.first;
  }
  var s = entry is String ? entry : key;
  args.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}
